# Pure static mirror of the documented deterministic selection contract.
import re

def norm(value):
    value=re.sub(r'([a-z0-9])([A-Z])',r'\1 \2',value)
    return ' '.join(value.replace('_',' ').replace('-',' ').lower().split())
def tokens(text, term):
    return re.search(r'(?:^|[^a-z0-9])'+re.escape(norm(term))+r'(?:$|[^a-z0-9])',text) is not None
def choose(params, resource):
    exact=['file id'] if resource=='folder' else ['spreadsheet id']
    terms=['file','folder','resource'] if resource=='folder' else ['spreadsheet']
    for required_only in (True,False):
        for name,item in params.items():
            if required_only and not item['required']: continue
            if norm(name) in exact: return name
    for required_only, metadata in ((True,False),(True,True),(False,True)):
        for name,item in params.items():
            if required_only and not item['required']: continue
            text=norm(name) if not metadata else norm(name+' '+item.get('description',''))
            if tokens(text,'id') and any(tokens(text,t) for t in terms): return name
    return ''
def missing(params,args):
    return [name for name,item in params.items() if item['required'] and not args.get(name)]
