+/**
+ * @return 'object'|'array'|''
+ */
+function editorial_handoff_rows_shape(array $schema): string
+{
+    $items = $schema['items'] ?? null;
+    if (!is_array($items)) {
+        return '';
+    }
+    if (isset($items['properties']) || (($items['type'] ?? '') === 'object')) {
+        return 'object';
+    }
+    if (($items['type'] ?? '') === 'array' || isset($items['items'])) {
+        return 'array';
