+        'drive_file_id' => (string) ($sync['drive_file_id'] ?? ''),
+        'sync_status' => 'failed',
+        'code' => $code,
+    ]);
+    return ['ok' => false, 'code' => $code, 'message' => $safeMessage];
+}
